  async function compareStudies(){const aid=$('compareA').value,bid=$('compareB').value;if(!aid||!bid||aid===bid){toast('Choose two different studies');return}const [a,b]=await Promise.all([studyStorage.get(aid),studyStorage.get(bid)]),grid=$('compareGrid');grid.replaceChildren();for(const study of [a,b]){const item=document.createElement('div');item.className='compare-item';const img=document.createElement('img');img.src=study.preview;const h=document.createElement('h3');h.textContent=study.name;const p=document.createElement('p');p.textContent=`${study.engine.position} splits · ${study.engine.settings.priorityModel} model`;item.append(img,h,p);grid.append(item)}$('compareDialog').showModal()}

