  function shareSettings(){const s=settingsFromUI(),params=new URLSearchParams;for(const [k,v] of Object.entries(s))params.set(k,v);params.set('budget',currentBudget());params.set('compare',$('compareRange').value);const url=`${location.href.split('?')[0]}?${params}`;history.replaceState(null,'',url);navigator.clipboard?.writeText(url).then(()=>toast('Settings URL copied')).catch(()=>toast('Settings added to the address bar'))}
  function applyURLSettings(){const p=new URLSearchParams(location.search);if(!p.size)return;for(const id of ['priorityModel','channelMode','representative','splitMode','minWidth','minHeight','areaWeight','noiseBlur','qualityTarget'])if(p.has(id)&&$(id))$(id).value=p.get(id);if(p.has('budget'))syncBudget(p.get('budget'));if(p.has('compare'))$('compareRange').value=p.get('compare');updateControlLabels()}

